import {validateBrief} from './validator.mjs';
import examples from './examples.mjs';
const $=id=>document.getElementById(id);
const copy={ru:{skip:'К редактору',language:'Язык',kicker:'Рабочие инструменты / 0.1.0',title:'Бриф без пробелов.',intro:'Проверьте структуру задания до разговора с продюсером. Весь текст остаётся в этой вкладке.',editTitle:'Ваш бриф',exampleLabel:'Начните с демонстрационного примера',load:'Загрузить',synthetic:'Все примеры синтетические: это не клиентские проекты. Загрузка заменяет текст редактора.',editorLabel:'Текст брифа в JSON',editorHelp:'До 100 000 символов. Можно вставить свой JSON или изменить пример. Ctrl / ⌘ + Enter — проверить.',check:'Проверить бриф',saveBrief:'Скачать JSON',reviewTitle:'Результат проверки',saveReport:'Скачать отчёт',limitsTitle:'Что проверяется',limits:'Обязательные поля, типы данных и формат даты по общей схеме брифа SHAR. Полный бриф ещё не означает согласованное ТЗ: инструмент не оценивает бюджет, творческое качество, сроки или юридические права.',schema:'Скачать схему проверки',dataset:'Скачать исходные примеры',privacy:'Без регистрации, аналитики и отправки брифа. При закрытии вкладки текст не сохраняется. Скачивайте только те материалы, которые готовы хранить на своём устройстве.',contact:'Обсудить проект с SHAR ↗',contactHint:'Откроется сайт SHAR. Бриф не передаётся автоматически.',ready:'Готов к проверке',readyBody:'Измените пример и нажмите «Проверить бриф».',stale:'Текст изменён',staleBody:'Проверьте заново, чтобы получить актуальный результат.',valid:'Структура заполнена',validBody:'Проверка схемы пройдена. Обсудите содержание и условия с продюсером.',invalid:'Есть замечания',invalidBody:'Исправьте перечисленные поля и повторите проверку.',syntax:'Некорректный JSON. Проверьте кавычки, запятые и скобки или загрузите пример.',large:'Превышен лимит 100 000 символов. Сократите бриф.',empty:'Вставьте JSON или загрузите пример.',pageTitle:'Проверка брифа — SHAR Production'},en:{skip:'Skip to editor',language:'Language',kicker:'Production tools / 0.1.0',title:'A brief with no gaps.',intro:'Check your project structure before speaking with a producer. Everything you enter stays in this tab.',editTitle:'Your brief',exampleLabel:'Start with a demonstration example',load:'Load',synthetic:'All examples are synthetic, not client projects. Loading replaces the editor text.',editorLabel:'Brief as JSON',editorHelp:'Up to 100,000 characters. Paste your JSON or edit an example. Ctrl / ⌘ + Enter to check.',check:'Check brief',saveBrief:'Download JSON',reviewTitle:'Validation result',saveReport:'Download report',limitsTitle:'What this checks',limits:'Required fields, data types and date format against the shared SHAR brief schema. Completeness does not mean an agreed specification: this tool does not assess budget, creative quality, feasibility or legal rights.',schema:'Download validation schema',dataset:'Download source examples',privacy:'No login, analytics or brief submission. Closing this tab discards the text. Download only material you are comfortable storing on your device.',contact:'Discuss a project with SHAR ↗',contactHint:'Opens the SHAR website. Your brief is not transferred automatically.',ready:'Ready to check',readyBody:'Edit the example, then select Check brief.',stale:'Text changed',staleBody:'Check again for an up-to-date result.',valid:'Structure complete',validBody:'Schema validation passed. Discuss the content and terms with a producer.',invalid:'Needs attention',invalidBody:'Correct the fields below and check again.',syntax:'Invalid JSON. Check quotes, commas and brackets, or load an example.',large:'The 100,000-character limit was exceeded. Shorten the brief.',empty:'Paste JSON or load an example.',pageTitle:'Brief checker — SHAR Production'}};
let language='ru', report=null, state='ready';
function render(){const t=copy[language];document.documentElement.lang=language;document.title=t.pageTitle;document.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t[el.dataset.i18n]);const result=$('result');result.replaceChildren();const h=document.createElement('h3');h.textContent=t[state];const p=document.createElement('p');p.textContent=t[state+'Body'];result.append(h,p);if(report?.errors.length){const ol=document.createElement('ol');for(const error of report.errors){const li=document.createElement('li'),code=document.createElement('code'),message=document.createElement('span');code.textContent=error.path||'$';message.textContent=error.message;li.append(code,message);ol.append(li)}result.append(ol)}$('save-report').disabled=!report;$('editor').setAttribute('aria-invalid',String(state==='invalid'));}
function check(focus=true){const raw=$('editor').value,t=copy[language];let error=null,value;if(raw.length>100000)error={path:'$',code:'input_limit',message:t.large};else if(!raw.trim())error={path:'$',code:'empty_input',message:t.empty};else try{value=JSON.parse(raw)}catch{error={path:'$',code:'json_syntax',message:t.syntax}}report=error?{valid:false,errors:[error]}:validateBrief(value,{language});state=report.valid?'valid':'invalid';render();if(focus)$('result').focus();return report;}
function dirty(){report=null;state='stale';render()}
function selectExamples(){const selected=$('example').value;$('example').replaceChildren();for(const [i,example] of examples.entries()){if(example.language!==language)continue;const option=document.createElement('option');option.value=String(i);option.textContent=example.title;$('example').append(option)}if([...$('example').options].some(x=>x.value===selected))$('example').value=selected;}
function load(){const example=examples[Number($('example').value)];$('editor').value=JSON.stringify(example.brief,null,2);report=null;state='ready';render();}
function download(name,value){const url=URL.createObjectURL(new Blob([value],{type:'application/json;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
$('language').addEventListener('change',()=>{language=$('language').value;selectExamples();if(report)check(false);else render()});$('load').addEventListener('click',load);$('editor').addEventListener('input',dirty);$('check').addEventListener('click',()=>check());$('editor').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();check()}});$('save-brief').addEventListener('click',()=>{if(check(false).valid)download('production-brief.json',JSON.stringify(JSON.parse($('editor').value),null,2));else $('result').focus()});$('save-report').addEventListener('click',()=>{if(report)download('brief-validation.json',JSON.stringify({tool:'shar-brief-browser',version:'0.1.0',language,...report},null,2))});selectExamples();load();
